// The sample PICS, project/sample-pics, and the task page integrate/pics
// (#1496). The sample is generated by
// crates/bacnet-integration-tests/sample_pics.rs, and a Rust test fails when
// the committed page is stale; these tests check the banner travels with it
// into the plain-text export, and keep both pages free of conformance claims.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { frontmatter, plainBody } from '../../scripts/content.mjs';
import { release, repository } from '../../src/lib/site.mjs';

const site = 'https://jscott3201.github.io/rusty-bacnet/';
const forbidden = /\b(conformant|compliant|certified)\b/i;
const reference = 'catalogue reference configuration';
const banner = `:::caution[Generated sample for the ${reference} only]`;
const pics = '## BACnet Protocol Implementation Conformance Statement (PICS)';

async function page(path) {
  const file = fileURLToPath(new URL(`../../src/content/docs/${path}`, import.meta.url));
  const source = await readFile(file, 'utf8');
  const { title, description, body } = frontmatter(source);
  return { source, title, description, body: await plainBody(body, file, []) };
}

const sample = await page('project/sample-pics.md');
const task = await page('integrate/pics.mdx');

test('the sample names its configuration in the title and opens with its banner', () => {
  assert.equal(sample.title, `Sample PICS: the ${reference}`);
  assert.match(sample.description, new RegExp(`for the ${reference} only`));
  assert.match(sample.source, /^<!-- Generated by crates\/bacnet-integration-tests\/sample_pics\.rs;/m);
  // The plain-text export is the page's body: the banner, inside the file,
  // comes before the generator's output, and the generated-file comment doesn't.
  assert.ok(sample.body.startsWith(banner), 'the export opens with the banner');
  assert.ok(sample.body.indexOf(banner) < sample.body.indexOf(pics));
  assert.ok(sample.body.includes('It is not a claim for any product or device'));
  assert.doesNotMatch(sample.body, /<!--/);
  assert.ok(sample.body.includes(`(${site}integrate/pics/)`), 'the banner sends readers to the task page');
});

test('the sample is the generator output for the documented configuration', () => {
  // Version fields follow the release the site names; nothing varies per run.
  assert.ok(sample.source.includes(`| Firmware Revision | ${release} |`));
  assert.ok(sample.source.includes(`| Application Software Version | ${release} |`));
  for (const line of ['- BACnet/IP (Annex J)', '- BACnet/SC (Annex AB)', '| Router | false |', '| BBMD | false |', '| Foreign Device | false |']) {
    assert.ok(sample.source.includes(`\n${line}\n`), line);
  }
  // The generator's headings sit one level below the page title.
  assert.doesNotMatch(sample.source, /^# /m);
  assert.equal(sample.source.split(`\n${pics}\n`).length, 2);
  // One generated region around the generator's output, which gives the page
  // the generated pages' low search weight; the banner stays outside it.
  const start = sample.source.indexOf('\n<!-- generated:start ');
  const end = sample.source.indexOf('\n<!-- generated:end -->\n');
  assert.equal(sample.source.split('generated:start').length, 2);
  assert.ok(sample.source.indexOf(banner) < start && start < sample.source.indexOf(pics) && sample.source.indexOf(pics) < end);
  // No code fences: the sample harness has nothing to run here.
  assert.doesNotMatch(sample.source, /^```/m);
});

test('neither page claims conformance or names a building block', () => {
  for (const [name, { source, body }] of [['sample', sample], ['task', task]]) {
    assert.doesNotMatch(source, forbidden, name);
    assert.doesNotMatch(body, forbidden, name);
    assert.doesNotMatch(source, /\bBIBB/, name);
  }
});

test('the task page covers each surface and links the sample and the tables', () => {
  assert.equal(task.title, 'Generate a PICS for your device');
  assert.ok(task.description);
  for (const heading of ['## Choose where to generate it', '## Generate one in Rust', '## What the generator fills in', '### Details read from the Device', '## What you fill in', '## Read the output', '## Next steps']) {
    assert.equal(task.body.split(`\n${heading}\n`).length, 2, heading);
  }
  assert.ok(task.body.includes('server.generate_pics(&PicsConfig)'));
  // One release-scoped page: no dev section, no pointer to one.
  assert.ok(!task.body.includes('On `dev`') && !task.body.includes('on-dev-after-the-release'));
  assert.ok(task.body.includes('PicsGenerator::INITIATED_SERVICES'));
  // The program claims no profile and takes the product and protocol details
  // from its Device (#2125, #2137): its PicsConfig sets none of them.
  assert.ok(task.body.includes('DeviceProfile::Custom("None claimed".into())'));
  assert.ok(!task.body.includes('DeviceProfile::BAsc'));
  assert.ok(task.body.includes('bacnet_types::PROTOCOL_REVISION'));
  assert.ok(!task.body.includes('PropertyIdentifier::PROTOCOL_REVISION'));
  const rust = [...task.body.matchAll(/^```rust\n([\s\S]*?)^```/gm)].map(match => match[1]);
  assert.equal(rust.length, 1, 'one Rust program');
  const config = rust[0].slice(rust[0].indexOf('let pics_config = PicsConfig {'));
  for (const field of ['vendor_name', 'model_name', 'firmware_revision', 'application_software_version', 'protocol_version', 'protocol_revision']) {
    assert.ok(!config.slice(0, config.indexOf('};')).includes(field), field);
  }
  assert.doesNotMatch(task.source, /building block/i);
  assert.ok(task.body.includes(`the bindings have no PICS generator in v${release}`));
  assert.ok(task.body.includes('no `bacnet` command generates a PICS'));
  assert.ok(task.body.includes(`(${site}project/sample-pics/)`));
  assert.ok(task.body.includes(`(${site}project/conformance/)`));
  assert.ok(task.body.includes(`(${repository}/blob/v${release}/docs/rust-api.md#bacnet-server)`));
  // The table names each PicsConfig field once.
  return readFile(new URL('../../../crates/bacnet-server/src/pics/mod.rs', import.meta.url), 'utf8').then(generator => {
    const config = generator.slice(generator.indexOf('pub struct PicsConfig {'), generator.indexOf('impl Default for PicsConfig'));
    const fields = [...config.matchAll(/^ {4}pub (\w+):/gm)].map(match => match[1]);
    const rows = task.source.slice(task.source.indexOf('| `PicsConfig` field |'), task.source.indexOf('Annex A asks for more'));
    const named = [...rows.matchAll(/`(\w+)`/g)].map(match => match[1]).filter(name => name !== 'PicsConfig' && !name.startsWith('DeviceProfile'));
    assert.deepEqual([...new Set(named)].sort(), [...fields].sort(), 'the table names each PicsConfig field once');
  });
});

test('the pages that discuss PICS link the task page and the sample', async () => {
  const conformance = await page('project/conformance.mdx');
  const support = await page('project/support.md');
  for (const [name, { body }] of [['conformance', conformance], ['support', support]]) {
    assert.ok(body.includes(`(${site}integrate/pics/)`), name);
    assert.ok(body.includes(`(${site}project/sample-pics/)`), name);
  }
  const server = await page('integrate/server.mdx');
  assert.ok(server.body.includes(`(${site}integrate/pics/)`));
});
